<?php /** @var array $rows @var int $page @var int $pages @var string $filter */ use Wordless\Activity; ?>
<nav class="tabs"><?php foreach (['' => __('Tout'), 'login' => __('Connexions'), 'login_failed' => __('Échecs de connexion'), 'publish' => __('Publications'), 'settings' => __('Réglages'), 'mcp' => __('IA connectée')] as $k => $l): ?><a href="<?= e(admin_url('activity' . ($k !== '' ? '?action=' . $k : ''))) ?>"<?= $filter === $k ? ' aria-current="page"' : '' ?>><?= e($l) ?></a><?php endforeach ?></nav>
<section class="panel"><?php if ($rows): ?><ul class="feed"><?php foreach ($rows as $a): ?><li><span><strong><?= e($a['user_name'] ?? __('Système')) ?></strong> <?= e(Activity::describe($a)) ?></span><time title="<?= e(fmt_date((int) $a['created_at'], 'datetime')) ?>"><?= e(human_time((int) $a['created_at'])) ?></time></li><?php endforeach ?></ul><?php else: ?><div class="empty"><p><?= e(__('Rien à afficher.')) ?></p></div><?php endif ?></section>
<?php if ($pages > 1): ?><nav class="actions-row" style="margin-top:1rem"><?php for ($i = 1; $i <= min($pages, 20); $i++): ?><a class="btn btn-sm<?= $i === $page ? ' btn-primary' : '' ?>" href="<?= e(admin_url('activity?p=' . $i . ($filter !== '' ? '&action=' . $filter : ''))) ?>"><?= $i ?></a><?php endfor ?></nav><?php endif ?>
